import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.DoUXNnsN.js";const S=JSON.parse('{"title":"ISA-95","description":"","frontmatter":{"title":"ISA-95","aliases":["ANSI/ISA-95","IEC 62264","ISA95"],"tags":["制造业务","地图","标准"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/ISA-95","https://en.wikipedia.org/wiki/Manufacturing_execution_system","https://www.sw.siemens.com/en-US/technology/isa-95-framework-layers/","https://reference.opcfoundation.org/specs/OPC-10030/4.2.3","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"80-电子制造业务/地图/ISA-95.md","filePath":"80-电子制造业务/地图/ISA-95.md"}'),l={name:"80-电子制造业务/地图/ISA-95.md"};function i(d,t,n,h,s,u){return a(),o("div",null,[...t[0]||(t[0]=[r('<blockquote><p>本篇是&quot;电子制造业务&quot;这一块的<strong>地图</strong>之一。读完你应该能：说出 ISA-95 把工厂的信息系统分成哪几层、每层管什么；判断一个系统（ERP、MES、PLC、温控器……）属于哪一层；理解为什么数据在层与层之间要&quot;翻译&quot;。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>ISA-95（国际上对应的标准是 IEC 62264）是一套国际标准，用来规定<strong>企业的管理系统和工厂的控制系统怎么分层、各层负责什么、层与层之间交换什么信息</strong>。它的核心价值是给大家一套统一的术语和模型。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li>对 <a href="/Encyclopedia/80-电子制造业务/ERP/ERP">ERP</a>、<a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a> 有个名字上的印象即可。读完本篇和 <a href="/Encyclopedia/80-电子制造业务/地图/电子制造信息系统全景图">电子制造信息系统全景图</a> 后，这几个词会清楚很多。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>一家工厂里往往有好几套系统：财务和订单在一套里，车间执行在另一套里，设备上还有自己的控制器。这些系统由不同的人、在不同的年代、从不同的厂商那里买来，各讲各的话：同一个&quot;工单&quot;，ERP 叫&quot;生产订单&quot;，车间叫&quot;制令&quot;，设备叫&quot;任务&quot;。</p><p>结果就是：系统之间对不上数、接口越做越乱、新人不知道某个功能该放在哪个系统里。</p><p>ISA-95 提供的是一张<strong>共同的地图</strong>，大家先对&quot;这件事归哪一层管&quot;达成一致，再谈接口怎么做。你可以把它想象成公司的<strong>组织架构图</strong>：董事会管战略，部门经理管排班，一线员工管动手，每一层关心的事情、说话的速度都不一样。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="五个层级" tabindex="-1">五个层级 <a class="header-anchor" href="#五个层级" aria-label="Permalink to &quot;五个层级&quot;">​</a></h3><p>ISA-95 把工厂的&quot;功能层次&quot;分成 Level 0 到 Level 4：</p><table tabindex="0"><thead><tr><th>层级</th><th>名称</th><th>这一层做什么</th><th>电子厂里的例子</th></tr></thead><tbody><tr><td>Level 4</td><td>业务计划与物流</td><td>管理制造运营所需的业务活动：接订单、排计划、采购、财务</td><td><a href="/Encyclopedia/80-电子制造业务/ERP/ERP">ERP</a>，还有 <a href="/Encyclopedia/80-电子制造业务/PLM/PLM">PLM</a>（产品资料）、<a href="/Encyclopedia/80-电子制造业务/APS/APS">APS</a>（排产）这类计划系统</td></tr><tr><td>Level 3</td><td>制造运营管理</td><td>把原料变成成品的工作流活动：工单执行、物料、质量、追溯</td><td><a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>、<a href="/Encyclopedia/80-电子制造业务/WMS/WMS">WMS</a>、<a href="/Encyclopedia/80-电子制造业务/QMS/QMS">QMS</a>、<a href="/Encyclopedia/80-电子制造业务/LIMS/LIMS">LIMS</a></td></tr><tr><td>Level 2</td><td>监视和控制</td><td>监视和控制物理过程，反应速度在亚秒级</td><td>设备的控制器、触摸屏（HMI）、SCADA、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a></td></tr><tr><td>Level 1</td><td>感知和操控</td><td>感知和操作物理过程</td><td>传感器、执行器、温控模块</td></tr><tr><td>Level 0</td><td>物理过程</td><td>真正发生的物理过程本身</td><td>炉膛加热、贴片头吸取元件、传送带转动</td></tr></tbody></table><p>（层级名称和说明来自 Siemens 和 OPC 基金会的整理；不同厂商对 Level 1、Level 2 的边界措辞略有差别，这里取常见说法。）</p><p><strong>怎么记</strong>：越往上越关心&quot;该做什么、做了多少、花了多少钱&quot;，节奏是按天、按班次、按订单；越往下越关心&quot;现在是多少度、是不是到位了&quot;，节奏是按秒、按毫秒。</p><h3 id="level-3-制造运营管理的四类活动" tabindex="-1">Level 3：制造运营管理的四类活动 <a class="header-anchor" href="#level-3-制造运营管理的四类活动" aria-label="Permalink to &quot;Level 3：制造运营管理的四类活动&quot;">​</a></h3><p>ISA-95 为 Level 3 的活动提供了参考模型，分成四类：<strong>生产、质量、维护、库存</strong>。这正好对应后面你会学到的几个系统：生产对应 <a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>，质量对应 <a href="/Encyclopedia/80-电子制造业务/QMS/QMS">QMS</a> 和 <a href="/Encyclopedia/80-电子制造业务/LIMS/LIMS">LIMS</a>，库存对应 <a href="/Encyclopedia/80-电子制造业务/WMS/WMS">WMS</a>，维护对应设备管理。需要说明的是，这是&quot;活动的分类&quot;，不是&quot;必须买几个软件&quot;：现实中一套 MES 可能同时包含质量和库存功能，也可能分开买。</p><h3 id="标准有哪几部分" tabindex="-1">标准有哪几部分 <a class="header-anchor" href="#标准有哪几部分" aria-label="Permalink to &quot;标准有哪几部分&quot;">​</a></h3><p>ISA-95 不是一份文件，而是一个系列：</p><table tabindex="0"><thead><tr><th>部分</th><th>内容</th></tr></thead><tbody><tr><td>Part 1</td><td>模型和术语：统一的术语和对象模型，决定&quot;要交换什么信息&quot;</td></tr><tr><td>Part 2</td><td>对象模型的属性：每个对象有哪些字段</td></tr><tr><td>Part 3</td><td>制造运营管理的模型：Level 3 的功能和活动</td></tr><tr><td>Part 4、Part 5</td><td>制造运营管理的对象模型与属性；商务与生产之间的交易</td></tr></tbody></table><p>具体的版本和修订年份，不同资料里写得不一致，需要用时请查标准发布机构的最新信息。例如 ISA 把 ANSI/ISA-95.00.01-2010 标注为对应 IEC 62264-1 的修改采用版本。</p><h3 id="它和-mes-的关系" tabindex="-1">它和 MES 的关系 <a class="header-anchor" href="#它和-mes-的关系" aria-label="Permalink to &quot;它和 MES 的关系&quot;">​</a></h3><p>MES 处在 Level 3，上面是 Level 4 的 ERP，下面是 Level 0 到 2 的设备与控制系统。据维基百科的介绍，ANSI/ISA-95（2000 年）把 MESA 的模型和 Purdue 参考模型合并在了一起。所以你会经常听到&quot;ISA-95 把 MES 定位在第三层&quot;。</p><h3 id="isa-95-是什么-不是什么" tabindex="-1">ISA-95 是什么，不是什么 <a class="header-anchor" href="#isa-95-是什么-不是什么" aria-label="Permalink to &quot;ISA-95 是什么，不是什么&quot;">​</a></h3><ul><li>它是<strong>模型和词汇表</strong>，不是软件，也没有规定你必须买哪家的产品。</li><li>它不要求你<strong>每一层、每一项活动</strong>都实现，小工厂可以只用其中一部分。</li><li>它不管具体用什么通信协议（比如 <a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a>），那是&quot;怎么传&quot;的问题，ISA-95 管的是&quot;传什么、归谁管&quot;。</li></ul><h2 id="逐步例子-一个炉温数据的旅程" tabindex="-1">逐步例子：一个炉温数据的旅程 <a class="header-anchor" href="#逐步例子-一个炉温数据的旅程" aria-label="Permalink to &quot;逐步例子：一个炉温数据的旅程&quot;">​</a></h2><p>用一个电子厂里最常见的场景，看一个数据怎么在五层之间走：回流焊炉的某个温区温度（回流焊见 <a href="/Encyclopedia/80-电子制造业务/地图/SMT与电子组装流程">SMT与电子组装流程</a>）。</p><ol><li><strong>Level 0</strong>：炉膛里的加热管发热，板子在传送带上经过，这是真实发生的物理过程。</li><li><strong>Level 1</strong>：热电偶感知温度，温控模块根据读数调节加热功率。</li><li><strong>Level 2</strong>：炉子的控制器和触摸屏汇总各温区的温度，显示给操作员，并保证各温区稳定在设定值上。这一层的反应是亚秒级的。</li><li><strong>Level 3</strong>：<a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a> 定时采集这个温度（也可能采集的是整条炉温曲线），把它和&quot;当前正在过炉的批次、板子&quot;关联起来，判断是否在工艺允许的范围里；超出范围就报警、拦截。</li><li><strong>Level 4</strong>：<a href="/Encyclopedia/80-电子制造业务/ERP/ERP">ERP</a> <strong>不关心</strong>每秒的温度。它只关心这一批板子的产出数量、合格数、成本和交期。</li></ol><p>再看反方向：<strong>工单</strong>是从 Level 4 的 ERP 里产生的，下发给 Level 3 的 MES，MES 再把&quot;生产哪个型号&quot;等要求落到设备的程序和参数上（Level 2）。数据每经过一层，都被&quot;翻译&quot;成这一层关心的样子：这就是为什么不能让 ERP 直接去读炉子的温度。</p><h2 id="动手实验-画出你们公司的系统分层图" tabindex="-1">动手实验：画出你们公司的系统分层图 <a class="header-anchor" href="#动手实验-画出你们公司的系统分层图" aria-label="Permalink to &quot;动手实验：画出你们公司的系统分层图&quot;">​</a></h2><p>这个实验不需要电脑，需要一张纸（或一份表格），十几分钟。</p><ol><li>列出你们公司（或实习的工厂）里你知道名字的所有系统和设备：财务软件、订单系统、MES、仓库系统、质检系统、贴片机、回流焊炉、条码枪、PLC……不会的就问同事&quot;这是干什么的&quot;。</li><li>对每一项判断：它主要管&quot;业务计划&quot;（Level 4）、&quot;车间运营&quot;（Level 3）、&quot;设备控制&quot;（Level 2）还是&quot;传感执行&quot;（Level 0/1）？</li><li>画一张五层的图，把它们放进去。</li><li>用箭头标出你知道的数据流：谁把数据交给谁？是工单、物料、检验结果还是设备参数？</li><li>标记出<strong>说不清归属</strong>的功能，比如某个报表是 MES 做的还是 ERP 做的。这些地方往往就是工作中最容易出问题、最值得向前辈请教的地方。</li></ol><h2 id="常见坑与误区" tabindex="-1">常见坑与误区 <a class="header-anchor" href="#常见坑与误区" aria-label="Permalink to &quot;常见坑与误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>事实</th></tr></thead><tbody><tr><td>&quot;ISA-95 是一个软件&quot;</td><td>它是标准和模型，没有任何软件叫 ISA-95</td></tr><tr><td>&quot;MES 是控制设备的&quot;</td><td>控制设备是 Level 1–2 的事（PLC、设备控制器）；MES 在上层，负责计划执行、记录和追溯</td></tr><tr><td>&quot;我们公司没有按五层来做，所以不符合标准&quot;</td><td>标准是参考地图，不是考试。关键是你能说清楚每件事归谁管</td></tr><tr><td>&quot;ERP 和 MES 重复，只留一个就行&quot;</td><td>它们的时间尺度和关心的对象不同，ERP 管订单与成本，MES 管工单执行与追溯；有些公司为了省事让一方&quot;兼职&quot;，但功能并没有消失</td></tr><tr><td>&quot;层级越高越重要&quot;</td><td>每一层都不可或缺，下层数据不准，上层的报表就全是错的</td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>贴片机里检测元件有没有被吸起来的传感器，属于哪一层？ <strong>答</strong>：Level 1（感知和操控）。传感器和执行器在这一层，贴片机的整机控制器在 Level 2。</li><li>&quot;本月计划生产 5000 块板&quot;这个信息，最早出现在哪一层？ <strong>答</strong>：Level 4。订单与计划是 ERP（或 APS）这一层管理的。</li><li>为什么 ERP 不直接读取回流焊炉的实时温度？ <strong>答</strong>：两层的时间尺度和关心的东西不同：炉温要亚秒级响应、关注工艺是否稳定；ERP 关心订单、数量和成本。中间需要 MES 这一层把设备数据整理、关联到批次后，再把结果（如合格数、完工数）交给 ERP。</li><li><a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a> 处在 ISA-95 的哪一层？它上面和下面分别是什么？ <strong>答</strong>：Level 3。上面是 Level 4 的 ERP，下面是 Level 0 到 2 的设备和控制系统。</li><li>判断对错：&quot;ISA-95 规定了企业必须购买同一个厂商的 MES 和 ERP。&quot; <strong>答</strong>：错。ISA-95 只规定模型和术语，不规定使用哪家的产品。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ISA-95（IEC 62264）把工厂分成 Level 0 到 Level 4 五层：物理过程、感知操控、监视控制、制造运营管理、业务计划。</li><li>MES 在 Level 3，ERP 在 Level 4，设备控制在 Level 1–2。</li><li>Level 3 的活动分生产、质量、维护、库存四类。</li><li>数据每过一层要&quot;翻译&quot;成这一层关心的样子。</li><li>它是模型和词汇，不是软件，也不要求全部实现。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/80-电子制造业务/MES/MES">MES</a>、<a href="/Encyclopedia/80-电子制造业务/ERP/ERP">ERP</a>、<a href="/Encyclopedia/70-工业通信与自动化/PLC">PLC</a>、<a href="/Encyclopedia/80-电子制造业务/地图/电子制造信息系统全景图">电子制造信息系统全景图</a>、<a href="/Encyclopedia/80-电子制造业务/地图/SMT与电子组装流程">SMT与电子组装流程</a>、<a href="/Encyclopedia/70-工业通信与自动化/Modbus/Modbus">Modbus</a>、<a href="/Encyclopedia/70-工业通信与自动化/OPC-UA">OPC-UA</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>维基百科 ISA-95 词条：<a href="https://en.wikipedia.org/wiki/ISA-95" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/ISA-95</a></li><li>Siemens 对 ISA-95 各层的说明：<a href="https://www.sw.siemens.com/en-US/technology/isa-95-framework-layers/" target="_blank" rel="noreferrer">https://www.sw.siemens.com/en-US/technology/isa-95-framework-layers/</a></li><li>OPC 基金会对 ISA-95 层级的描述：<a href="https://reference.opcfoundation.org/specs/OPC-10030/4.2.3" target="_blank" rel="noreferrer">https://reference.opcfoundation.org/specs/OPC-10030/4.2.3</a></li></ul>',42)])])}const q=e(l,[["render",i]]);export{S as __pageData,q as default};
